{
  "name": "SCARA机械臂",
  "name_en": "SCARA Robotic Arm",
  "manufacturer": "",
  "description": "一种带夹爪的SCARA（水平关节型）机械臂，用于实验室自动化中的定位、搬运与取放操作。它可按笛卡尔坐标或关节坐标移动，并执行回零、安全位移动以及板类实验耗材的抓取和放置。",
  "description_en": "A SCARA robotic arm with a gripper for laboratory automation tasks such as positioning, transport, and pick-and-place operations. It can move in Cartesian space or joint space and perform homing, safe-position moves, and handling of plate-like lab consumables.",
  "tag_hints": [
    "SCARA robot",
    "lab automation",
    "pick-and-place",
    "robotic gripper",
    "plate handling",
    "Cartesian positioning",
    "joint-space motion"
  ],
  "actions": [
    {
      "action_name": "auto-move_to",
      "description": "将机械臂移动到指定的三维位置或关节位置。",
      "description_en": "Move the arm to a specified 3D position or joint-space position."
    },
    {
      "action_name": "auto-get_joint_position",
      "description": "获取机械臂当前关节空间位置。",
      "description_en": "Get the current joint-space position of the arm."
    },
    {
      "action_name": "auto-get_cartesian_position",
      "description": "获取机械臂当前笛卡尔空间位置。",
      "description_en": "Get the current Cartesian position of the arm."
    },
    {
      "action_name": "auto-open_gripper",
      "description": "将夹爪张开到指定宽度。",
      "description_en": "Open the gripper to a specified width."
    },
    {
      "action_name": "auto-close_gripper",
      "description": "将夹爪闭合到指定宽度。",
      "description_en": "Close the gripper to a specified width."
    },
    {
      "action_name": "auto-is_gripper_closed",
      "description": "检查夹爪是否处于闭合状态。",
      "description_en": "Check whether the gripper is closed."
    },
    {
      "action_name": "auto-halt",
      "description": "停止机械臂当前运动。",
      "description_en": "Stop any ongoing movement of the arm."
    },
    {
      "action_name": "auto-home",
      "description": "使机械臂回零到默认位置。",
      "description_en": "Home the arm to its default position."
    },
    {
      "action_name": "auto-move_to_safe",
      "description": "将机械臂移动到预定义的安全位置。",
      "description_en": "Move the arm to a predefined safe position."
    },
    {
      "action_name": "auto-approach",
      "description": "将机械臂移动到目标附近的接近位置。",
      "description_en": "Move the arm to an approach position near the target."
    },
    {
      "action_name": "auto-pick_up_resource",
      "description": "从指定位置抓取板类实验资源。",
      "description_en": "Pick up a plate-like lab resource from the specified position."
    },
    {
      "action_name": "auto-drop_resource",
      "description": "将板类实验资源放置到指定位置。",
      "description_en": "Place a plate-like lab resource at the specified position."
    }
  ]
}

